 return f'<button type="button" class="image-button" data-image="{e(path)}" data-title="{e(title)}" aria-label="{e(title)} 확대"><img src="{e(path)}" alt="{e(title)}" loading="lazy" decoding="async" width="941" height="1672"></button>'
